@import url("https://fonts.googleapis.com/css2?family=Nunito+Sans:wght@400;700&family=Fraunces:opsz,wght@9..144,700&display=swap");
/* Zapatería de barrio (T-023): misma paleta que la web de la tienda */
:root {
	--font-family: 'Nunito Sans', system-ui, sans-serif;
	--font-weight-bold: 700;
	--font-size-body: 14px;
	--font-size-label: 15px;
	--font-size-input: 16px;
	--font-size-header: 26px;
	--font-size-paragraph: 15px;
	--color-background: #f3ebdd;
	--color-card-bg: #fffaf1;
	--color-card-border: #dccab0;
	--color-card-shadow: rgba(58, 36, 24, 0.10);
	--color-link: #6a5444;
	--color-header: #2a1c13;
	--color-label: #2a1c13;
	--color-input-border: #dccab0;
	--color-input-text: #2a1c13;
	--color-focus-border: #1f4d3a;
	--color-submit-btn-bg: #7b4a2a;
	--color-submit-btn-text: #fffaf1;
	--color-error: #8b1d2c;
	--color-required: #8b1d2c;
	--color-clear-button-bg: #6a5444;
	--color-html-text: #2a1c13;
	--color-html-link: #7b4a2a;
	--color-header-subtext: #6a5444;
	--border-radius-card: 12px;
	--card-border-radius: 12px;
	--border-radius-input: 8px;
	--container-width: 480px;
}
/* Franja de cuero con el nombre de la tienda y una costura */
body::before {
	content: "Zapatería Paso Firme";
	display: block; align-self: stretch; width: 100%; box-sizing: border-box;
	padding: 18px 16px 22px; text-align: center;
	font-family: Fraunces, Georgia, serif; font-weight: 700; font-size: 22px; color: #fbf3e6;
	background: #3a2418 repeating-linear-gradient(90deg, #a77b55 0 10px, transparent 10px 17px) 0 calc(100% - 6px) / 100% 2px no-repeat;
}
/* Tarjeta con costura por dentro */
.card { position: relative; }
.card::before {
	content: ""; position: absolute; inset: 5px; pointer-events: none;
	border: 1.5px dashed #c9b08c; border-radius: 7px;
}
.form-header h1 { font-family: Fraunces, Georgia, serif; font-weight: 700; }
#submit-btn { outline: 1px dashed rgba(255, 250, 241, 0.55); outline-offset: -5px; }
#submit-btn:focus-visible { outline: 3px solid #1f4d3a; outline-offset: 2px; }
input, textarea, select, button { font-family: var(--font-family); }

