const sinAcentos = s => String(s ?? '').normalize('NFD').replace(/\p{M}/gu, '');

const clave = s => sinAcentos(s).toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();

// Busca un campo del formulario por su nombre interno o por su etiqueta, sin depender de acentos ni mayúsculas.
function campo(datos, ...nombres) {
  const k = Object.keys(datos).find(c => nombres.includes(clave(c)));
  return k === undefined ? '' : String(datos[k] ?? '').trim();
}

function numero(s) {
  let t = String(s ?? '').replace(/[€\s]/g, '');
  if (t.includes(',')) t = t.replace(/\./g, '').replace(',', '.');
  return /^\d+(\.\d+)?$/.test(t) ? Math.round(Number(t) * 100) / 100 : null;
}

function prepararConfirmacion(datos) {
  return {
    numero: numero(campo(datos, 'numero', 'n de solicitud', 'no de solicitud', 'numero de solicitud')),
    precio: numero(campo(datos, 'precio')),
    abono: numero(campo(datos, 'abono', 'abono inicial')),
    forma_pago: clave(campo(datos, 'forma pago', 'forma de pago')),
  };
}

return $input.all().map(i => ({ json: prepararConfirmacion(i.json) }));

const euros = n => `${Number(n).toFixed(2).replace('.', ',')} €`;

const MINIMO_ABONO = 5;

const FORMAS_PAGO = ['efectivo', 'tarjeta', 'bizum'];

function decidirConfirmaciones(confirmaciones, guardadas) {
  const confirmadasAhora = new Set();
  return confirmaciones.map(c => {
    const s = guardadas.find(g => Number(g.id) === c.numero);
    const no = motivo => ({ ...c, solicitud: s ?? null, accion: 'rechazar', motivo });
    if (!s) return no(`No existe la solicitud nº ${c.numero ?? '?'}`);
    if (s.estado === 'confirmada' || confirmadasAhora.has(s.id)) {
      return no(`La solicitud nº ${s.id} ya está confirmada${s.apartado_id ? ` (apartado #${s.apartado_id})` : ''}: no se crea otro apartado`);
    }
    if (c.precio === null || c.precio <= 0) return no('El precio no es un número mayor que 0');
    if (c.abono === null || c.abono < MINIMO_ABONO) return no(`El abono inicial tiene que ser de al menos ${euros(MINIMO_ABONO)}`);
    if (c.abono > c.precio) return no('El abono inicial no puede superar el precio');
    if (!FORMAS_PAGO.includes(c.forma_pago)) return no('La forma de pago tiene que ser efectivo, tarjeta o bizum');
    confirmadasAhora.add(s.id);
    return { ...c, solicitud: s, accion: 'crear', motivo: '',
      body: { cliente: s.cliente, telefono: s.telefono || null, email: s.email || null, producto: s.producto,
              talla: s.talla, precio: c.precio, abono_inicial: c.abono, forma_pago: c.forma_pago } };
  });
}

// Una solicitud ya confirmada (o confirmada antes en este mismo lote) no crea otro apartado.
const confirmaciones = $('Preparar confirmación').all().map(i => i.json);
const guardadas = $('Solicitudes guardadas').all().map(i => i.json).filter(g => g.id !== undefined);
return decidirConfirmaciones(confirmaciones, guardadas).map(json => ({ json }));

// 201: apartado creado. 422: la app lo rechaza (detail puede ser texto o lista). Otro código es un error.
const previo = $('Decidir confirmaciones').item.json;
const { statusCode, body } = $json;
if (statusCode === 201) return { json: { ...previo, creado: true, apartado: body } };
if (statusCode === 422) {
  const d = body?.detail;
  return { json: { ...previo, creado: false, motivo: `La app no lo acepta: ${typeof d === 'string' ? d : JSON.stringify(d)}` } };
}
throw new Error(`La tienda respondió ${statusCode} al crear el apartado: ${JSON.stringify(body)}`);

const euros = n => `${Number(n).toFixed(2).replace('.', ',')} €`;

function avisoResultado(r) {
  const s = r.solicitud;
  const quien = s ? `${s.cliente}, ${s.producto} T${s.talla}` : `solicitud nº ${r.numero ?? '?'}`;
  if (r.creado) {
    const a = r.apartado;
    return { destinatario: 'tienda', email: '', contexto: `Solicitud ${s.id}`,
      asunto: `Apartado #${a.id} creado desde la solicitud nº ${s.id}`,
      mensaje: ['Hola, Marisa:', '', `Se ha creado el apartado #${a.id} (${quien}).`,
        `Precio ${euros(a.precio)} · abonado ${euros(a.abonado)} · faltan ${euros(a.pendiente)} · vence el ${a.fecha_limite}.`,
        s.email ? 'La clienta recibirá la confirmación del apartado por correo.' : 'La clienta no dejó correo: avísala tú.', '',
        'Este aviso lo envía el flujo "Confirmar solicitud de apartado".'].join('\n') };
  }
  return { destinatario: 'tienda', email: '', contexto: s ? `Solicitud ${s.id}` : 'Confirmación de solicitud',
    asunto: `Apartado NO creado: ${quien}`,
    mensaje: ['Hola, Marisa:', '', `No se ha creado el apartado (${quien}).`, `Motivo: ${r.motivo}.`, '',
      'Revisa los datos y vuelve a enviar la confirmación.', '', 'Este aviso lo envía el flujo "Confirmar solicitud de apartado".'].join('\n') };
}

// Tras "Marcar como confirmada" el item es la fila de la tabla: el resultado se toma de "Comprobar creación".
return $input.all().map((i, k) => {
  const r = i.json.accion ? i.json : $('Comprobar creación').all().filter(x => x.json.creado)[k].json;
  return { json: avisoResultado(r) };
});
